UPDATE t_p24868917_kitchen_cost_calcula.doc_templates
SET blocks = '[
  {"id":"header","type":"header","label":"Шапка","content":"ДОГОВОР\nбытового подряда на изготовление мебели № {{номер_договора}}\nг. {{город}}  {{дата_договора}}","enabled":true},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера {{менеджер}}, действующего на основании доверенности № {{номер_доверенности}} от {{дата_доверенности}}, именуемый в дальнейшем «Подрядчик», и гр. {{имя_клиента}}, именуемый (ая) в дальнейшем «Заказчик», заключили настоящий Договор о нижеследующем:","enabled":true},
  {"id":"s1","type":"section","label":"1. ПРЕДМЕТ ДОГОВОРА","content":"1. ПРЕДМЕТ ДОГОВОРА","enabled":true},
  {"id":"s1p1","type":"paragraph","label":"1.1","content":"1.1. Подрядчик обязуется выполнить работу по изготовлению мебели и передать результат работы Заказчику, а Заказчик обязуется принять и оплатить результат работ.","enabled":true},
  {"id":"s1p2","type":"paragraph","label":"1.2","content":"1.2. Наименование, качественные характеристики, количество, дизайн мебели указываются в Техническом проекте, который является Приложением № 1 к настоящему Договору.","enabled":true},
  {"id":"s1p4","type":"paragraph","label":"1.4 — Срок изготовления","content":"1.4. Срок выполнения работ составляет {{срок_изготовления}} ({{срок_изготовления_прописью}}) рабочих дней с момента согласования Технического проекта и получения предварительной оплаты.","enabled":true},
  {"id":"s2","type":"section","label":"2. ТЕХНИЧЕСКИЙ ПРОЕКТ","content":"2. РАЗРАБОТКА И СОГЛАСОВАНИЕ ТЕХНИЧЕСКОГО ПРОЕКТА","enabled":true},
  {"id":"s2p1","type":"paragraph","label":"2.1","content":"2.1. Технический проект разрабатывается Подрядчиком в течение 10 (десяти) рабочих дней с момента получения предварительной оплаты.","enabled":true},
  {"id":"s3","type":"section","label":"3. СТОИМОСТЬ И РАСЧЁТЫ","content":"3. СТОИМОСТЬ РАБОТ И ПОРЯДОК РАСЧЁТОВ","enabled":true},
  {"id":"s3p1","type":"paragraph","label":"3.1 — Стоимость","content":"3.1. Общая стоимость работ составляет {{сумма}} ({{сумма_прописью}}) рублей, НДС не облагается.","enabled":true},
  {"id":"s3p2","type":"paragraph","label":"3.2 — Оплата","content":"3.2. Оплата работ осуществляется в следующем порядке:\n3.2.1. Предварительная оплата при заключении Договора.\n3.2.2. Окончательный платёж не позднее дня доставки.","enabled":true},
  {"id":"s4","type":"section","label":"4. ПРАВА И ОБЯЗАННОСТИ","content":"4. ПРАВА И ОБЯЗАННОСТИ СТОРОН","enabled":true},
  {"id":"s4p1","type":"paragraph","label":"4.1 — Обязанности подрядчика","content":"4.1. Подрядчик обязан:\n4.1.1. Выполнить работу по Договору согласно Техническому проекту и передать Заказчику мебель в установленный срок.\n4.1.2. Уведомить Заказчика о готовности мебели по электронной почте или путем обмена сообщениями (Telegram, WhatsApp, СМС и т.д.).\n4.1.3. Устранить недостатки, выявленные Заказчиком по результатам приемки работ.\n4.1.4. Предоставить Заказчику необходимую и достоверную информацию о предлагаемой работе, её видах и особенностях, о цене и форме оплаты.\n4.1.5. Предупредить Заказчика о возможных неблагоприятных последствиях выполнения его указаний о способе исполнения работы.","enabled":true},
  {"id":"s4p2","type":"paragraph","label":"4.2 — Обязанности заказчика","content":"4.2. Заказчик обязан:\n4.2.1. Согласовать и подписать Технический проект в срок, установленный Договором.\n4.2.2. Оплатить стоимость работ в соответствии с условиями настоящего Договора.\n4.2.3. Принять результат работ путем подписания Акта выполненных работ.\n4.2.4. Обеспечить сохранность помещения, в котором должна быть установлена мебель.\n4.2.5. Проводить ремонтно-отделочные работы в помещении только после получения письменного согласия Подрядчика.","enabled":true},
  {"id":"s4p3","type":"paragraph","label":"4.3 — Права подрядчика","content":"4.3. Подрядчик вправе:\n4.3.1. Требовать подписания Заказчиком Акта выполненных работ в течение 5 (пяти) календарных дней с даты передачи мебели.\n4.3.2. Требовать своевременной оплаты работ в соответствии с п. 3.2 настоящего Договора.\n4.3.3. Привлекать третьих лиц для исполнения обязательств по Договору.\n4.3.4. Приостановить работу в случае нарушения Заказчиком обязательств по Договору.\n4.3.5. В рекламных целях сделать фотоснимки изготовленной и установленной мебели.","enabled":true},
  {"id":"s4p4","type":"paragraph","label":"4.4 — Права заказчика","content":"4.4. Заказчик вправе:\n4.4.1. Выбрать модель мебели, цвет, компоновку, дизайн, материалы, фурнитуру.\n4.4.2. Отозвать согласие на обработку своих персональных данных Подрядчиком.","enabled":true},
  {"id":"s5","type":"section","label":"5. ГАРАНТИЯ","content":"5. ГАРАНТИЯ И КАЧЕСТВО ВЫПОЛНЕННЫХ РАБОТ","enabled":true},
  {"id":"s5g","type":"paragraph","label":"5 — Гарантийный срок","content":"Гарантийный срок на мебель (корпус, фасады, столешницы) составляет 24 месяца. Гарантийный срок на фурнитуру — 6 месяцев.","enabled":true},
  {"id":"s6","type":"section","label":"6. ПРИЁМКА","content":"6. ПОРЯДОК ПРИЁМКИ ВЫПОЛНЕННЫХ РАБОТ","enabled":true},
  {"id":"s6p1","type":"paragraph","label":"6.1–6.5","content":"6.1. По факту выполнения работ Подрядчик представляет Заказчику Акт выполненных работ в двух экземплярах. При необоснованном отказе одной из сторон от подписания акта он подписывается другой стороной в одностороннем порядке.\n6.2. Передача мебели производится по Акту выполненных работ, который составляется в момент передачи мебели.\n6.3. Приемка производится: при самовывозе — по адресу склада Подрядчика; при доставке — по адресу Заказчика.\n6.4. При самовывозе Подрядчик обеспечивает погрузку мебели на складе. Транспортировку и выгрузку осуществляет Заказчик.\n6.5. Заказчик обязан в течение 3 (трех) календарных дней с получения уведомления о готовности мебели прибыть на склад Подрядчика.","enabled":true},
  {"id":"s6p2","type":"paragraph","label":"6.6–6.13","content":"6.6. После погрузки мебели на транспортное средство Заказчика Подрядчик не несет ответственности за повреждения при транспортировке.\n6.7. При доставке Подрядчиком Заказчик обязан подготовить помещение и обеспечить бесплатную парковку на период отгрузки.\n6.8. При уклонении Заказчика от получения мебели Подрядчик хранит её бесплатно 7 (семь) дней, далее — 500 рублей за каждый день.\n6.10. При получении мебели Заказчик обязан осмотреть её, проверить качество, количество и комплектность.\n6.11. Риск случайной гибели и право собственности переходят к Заказчику с момента подписания документов о приемке.\n6.13. При отсутствии заказа на монтаж Заказчик осуществляет установку самостоятельно и за свой счет.","enabled":true},
  {"id":"s7","type":"section","label":"7. ОТВЕТСТВЕННОСТЬ","content":"7. ОТВЕТСТВЕННОСТЬ СТОРОН","enabled":true},
  {"id":"s7p1","type":"paragraph","label":"7.1–7.5","content":"7.1. Стороны несут ответственность за неисполнение обязательств по Договору в соответствии с Законом РФ «О защите прав потребителей».\n7.2. За нарушение сроков оплаты Подрядчик вправе потребовать неустойку (пени) в размере 0,1% от суммы задолженности за каждый день просрочки.\n7.3. Подрядчик не несет ответственности за невыполнение обязательств, вызванное неисполнением обязанностей Заказчика.\n7.4. При отказе Заказчика от мебели надлежащего качества, изготовленной по индивидуальному заказу, размер убытков Подрядчика составляет стоимость соответствующей партии мебели.\n7.5. При разгрузке мебели силами Заказчика материальную ответственность за сохранность груза несет Заказчик.","enabled":true},
  {"id":"s8","type":"section","label":"8. СПОРЫ","content":"8. ПОРЯДОК РАЗРЕШЕНИЯ СПОРОВ","enabled":true},
  {"id":"s8p1","type":"paragraph","label":"8.1–8.3","content":"8.1. Все споры и разногласия разрешаются путем переговоров между Сторонами.\n8.2. До передачи спора в суд Стороны предусматривают обязательный претензионный порядок. Направление претензии возможно по электронной почте или путем обмена сообщениями. Срок ответа на претензию — 10 (десять) рабочих дней.\n8.3. В случае невозможности разрешения разногласий путем переговоров споры решаются в судебном порядке в соответствии с действующим законодательством РФ.","enabled":true},
  {"id":"s9","type":"section","label":"9. СРОК ДЕЙСТВИЯ","content":"9. СРОК ДЕЙСТВИЯ ДОГОВОРА","enabled":true},
  {"id":"s9p1","type":"paragraph","label":"9.1–9.4","content":"9.1. Договор вступает в силу с момента его подписания обеими Сторонами и действует до полного исполнения обязательств.\n9.2. Изменения и дополнения к Договору принимаются по обоюдному соглашению Сторон путем подписания Дополнительного соглашения.\n9.3. Договор может быть расторгнут досрочно по письменному соглашению Сторон или в одностороннем порядке в случаях, предусмотренных законодательством РФ.\n9.4. В случае одностороннего отказа от Договора Заказчик обязуется оплатить Подрядчику фактически понесенные расходы.","enabled":true},
  {"id":"s10","type":"section","label":"10. ЗАКЛЮЧЕНИЕ","content":"10. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","enabled":true},
  {"id":"s10p1","type":"paragraph","label":"10.1–10.3","content":"10.1. При заключении Договора Стороны согласны на факсимильное воспроизведение подписи и обмен электронными копиями документов. Стороны признают юридически значимой переписку по электронной почте и в мессенджерах (Telegram, WhatsApp, СМС и т.д.).\n10.2. Стороны признают юридическую силу всех документов, направленных в электронном виде по указанным адресам электронной почты и номерам телефонов. Сообщение считается доставленным, если приложение подтверждает факт его отправки.\n10.3. Каждая Сторона обязуется обеспечивать конфиденциальность информации ограниченного доступа, полученной в связи с исполнением Договора.","enabled":true},
  {"id":"s10p2","type":"paragraph","label":"10.4–10.5","content":"10.4. Заказчик дает согласие на обработку своих персональных данных (ФИО, паспортные данные, адрес, телефон, e-mail, фотографии изделий) в целях исполнения настоящего договора на срок его действия и 12 месяцев после подписания Акта выполненных работ.\n10.5. К настоящему Договору прилагаются и являются его неотъемлемой частью:\n1. Технический проект.\n2. Калькуляция работ.\n3. Правила эксплуатации корпусной мебели.\n4. Образец Акта выполненных работ.","enabled":true},
  {"id":"s11","type":"section","label":"11. РЕКВИЗИТЫ СТОРОН","content":"11. РЕКВИЗИТЫ СТОРОН","enabled":true},
  {"id":"s11p1","type":"paragraph","label":"11 — Реквизиты","content":"Подрядчик: {{компания}}\nМенеджер: {{менеджер}}\n\n_________________________\n(подпись) М.П.\n\nЗаказчик: {{имя_клиента}}\n\n_________________________\n(подпись)","enabled":true}
]'::jsonb,
updated_at = now()
WHERE id = '9e390872-016f-468d-96e1-f0a526bdc3ea';
